        rom[27*40+32]=8'h20; rom[27*40+33]=8'h20; rom[27*40+34]=8'h20; rom[27*40+35]=8'h20; rom[27*40+36]=8'h20; rom[27*40+37]=8'h20; rom[27*40+38]=8'h20; rom[27*40+39]=8'h20;

    end

    always @(posedge clk) begin
        if ((line_idx < NUM_LINES) && (char_idx < LINE_WIDTH))
            char_out <= rom[line_idx * LINE_WIDTH + char_idx];
        else
            char_out <= 8'h20;
    end

endmodule
